// RINGKASAN ALUR BROADCAST:
// Bendera hijau → semua sprite ke posisi
// Klik Robot A:
//   Robot A → 'dialog-B1' → Robot B bereaksi
//   Robot A → 'dialog-B2' → Robot B bereaksi
//   Robot A → 'selesai' → Narator bereaksi

// Tidak ada kode baru di sini — semua sudah di node sebelumnya.
// Pastikan urutan broadcast benar:
// dialog-B1 → dialog-B2 → selesai

// Tips: gunakan broadcast 'dan tunggu' di Robot A
// agar dialog tidak tumpang tindih

starterCode.content:
// Daftar broadcast yang direncanakan:
// dialog-1, dialog-2, dialog-3, dialog-4
// dialog-5, dialog-6, dialog-7, dialog-8
// scene-2 (ganti backdrop), selesai

// Karakter A (klik untuk mulai)
[ketika sprite ini diklik]
[katakan [Dialog 1...] selama [2] detik]
[kirim pesan [dialog-2 ▼] dan tunggu]
[katakan [Dialog 3...] selama [2] detik]
[kirim pesan [dialog-4 ▼] dan tunggu]
// dst...

// Karakter B
[ketika menerima [dialog-2 ▼]]
[katakan [Dialog 2...] selama [2] detik]

// Karakter C
[ketika menerima [dialog-4 ▼]]
[katakan [Dialog 4...] selama [2] detik]
[kirim pesan [dialog-5 ▼]]
